options.getOption:
if (!context.panel.data?.series?.length) {
  return {};
}

const frame = context.panel.data.series[0];

const getField = (name) =>
  frame.fields.find(
    f =>
      f.name === name ||
      f.config?.displayName === name ||
      f.config?.displayNameFromDS === name
  );

const timeField = getField("Time");
const fit01Field = getField("Daily Flow FIT 600-01");
const fit02Field = getField("Daily Flow FIT 600-02");
const totalField = getField("Total");

if (!timeField || !fit01Field || !fit02Field) {
  return {
    title: {
      text: "Required fields not found"
    }
  };
}

const times = Array.from(timeField.values);
const fit01 = Array.from(fit01Field.values);
const fit02 = Array.from(fit02Field.values);

const total = totalField
  ? Array.from(totalField.values)
  : fit01.map((v, i) => Number(v || 0) + Number(fit02[i] || 0));

const labels = times.map(t =>
  new Intl.DateTimeFormat("en-GB", {
    timeZone: "Asia/Kolkata",
    day: "2-digit",
    month: "short"
  }).format(new Date(t))
);

return {
  tooltip: {
    trigger: "axis",
    axisPointer: {
      type: "shadow"
    },
    formatter: function (params) {
      const idx = params[0].dataIndex;

      let html = `<b>${labels[idx]}</b><br/>`;

      params.forEach(p => {
        const value =
          typeof p.value === "object"
            ? p.value.value
            : p.value;

        html += `${p.marker} ${p.seriesName}: ${Math.round(value)} Kg<br/>`;
      });

      html += `<b>Total: ${Math.round(total[idx] || 0)} Kg</b>`;

      return html;
    }
  },

  legend: {
    data: [
      "FIT 600-01",
      "FIT 600-02"
    ],
    bottom: 0
  },

  grid: {
    left: "5%",
    right: "4%",
    bottom: "15%",
    containLabel: true
  },

  xAxis: {
    type: "category",
    data: labels,
    axisLabel: {
      interval: Math.max(
        0,
        Math.floor(labels.length / 6)
      ),
    }
  },

  yAxis: {
    type: "value",
    name: "Kg"
  },

  series: [
    {
      name: "FIT 600-01",
      type: "bar",
      stack: "total",
      barCategoryGap: "35%",
      itemStyle: {
        color: "#5470C6"
      },
      data: fit01.map(v =>
        v > 0
          ? Math.round(v)
          : {
            value: 0,
            itemStyle: {
              opacity: 0
            }
          }
      )
    },

    {
      name: "FIT 600-02",
      type: "bar",
      stack: "total",
      barCategoryGap: "35%",
      itemStyle: {
        color: "#91CC75"
      },
      data: fit02.map(v =>
        v > 0
          ? Math.round(v)
          : {
            value: 0,
            itemStyle: {
              opacity: 0
            }
          }
      ),

      label: {
        show: true,
        position: "top",
        formatter: function (params) {
          const value = total[params.dataIndex];
          return value > 0 ? Math.round(value) : "";
        }
      }
    }
  ]
};

