options.getOption:
if (!context.panel.data?.series?.length) {
  return {
    xAxis: { type: "category", data: [] },
    yAxis: { type: "value" },
    series: []
  };
}

const frame = context.panel.data.series[0];

const timeData =
  Array.from(frame.fields.find(f => f.name === "Time")?.values ?? []);

const fit60001 =
  Array.from(frame.fields.find(f => f.name === "FIT 600-01")?.values ?? []);

const fit60002 =
  Array.from(frame.fields.find(f => f.name === "FIT 600-02")?.values ?? []);

const total =
  Array.from(frame.fields.find(f => f.name === "Total")?.values ?? []);

// Format timestamps to IST
const labels = timeData.map(t => {
  const date = new Date(t);

  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: "Asia/Kolkata",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    hour12: false
  }).formatToParts(date);

  const month = parts.find(p => p.type === "month")?.value || "00";
  const day = parts.find(p => p.type === "day")?.value || "00";
  const hour = parts.find(p => p.type === "hour")?.value || "00";

  return `${month}/${day} ${hour}:00`;
});

return {
  tooltip: {
    trigger: "axis",
    axisPointer: {
      type: "shadow"
    },
    formatter: function (params) {
      let text = `${params[0].axisValue}<br/>`;

      params.forEach(item => {
        const value =
          typeof item.value === "object"
            ? item.value.value
            : item.value;

        text += `${item.marker} ${item.seriesName}: ${Math.round(value)} Kg<br/>`;
      });

      const idx = params[0].dataIndex;

      if (total[idx] != null) {
        text += `<b>Total: ${Math.round(total[idx])} Kg</b>`;
      }

      return text;
    }
  },

  legend: {
    data: ["FIT 600-01", "FIT 600-02"],
    bottom: 0
  },

  grid: {
    left: "5%",
    right: "4%",
    bottom: "15%",
    containLabel: true
  },

  xAxis: {
    type: "category",
    data: labels,
    axisLabel: {
      rotate: 45
    }
  },

  yAxis: {
    type: "value",
    name: "Kg"
  },

  series: [
    {
      name: "FIT 600-01",
      type: "bar",
      stack: "total",
      itemStyle: {
        color: "#5470C6"
      },
      data: fit60001.map(v =>
        v == null || v <= 0
          ? { value: 0, itemStyle: { opacity: 0 } }
          : Math.round(v)
      )
    },
    {
      name: "FIT 600-02",
      type: "bar",
      stack: "total",
      itemStyle: {
        color: "#91CC75"
      },
      data: fit60002.map(v =>
        v == null || v <= 0
          ? { value: 0, itemStyle: { opacity: 0 } }
          : Math.round(v)
      ),
      label: {
        show: true,
        position: "top",
        formatter: function (params) {
          return Math.round(total[params.dataIndex] || 0);
        }
      }
    }
  ]
};

